using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class WorldPropOperations : RefCounted
{
    private readonly WorldSourceOperations _sources=new();
    private readonly WorldForestOperations _forests=new();
    private readonly RoadSectionOperations _sections=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public Resource create(Resource source,Variant model,string mode)
    {
        var next=_sources.copy(source);string title=model.ToString().GetFile().GetBaseName();if(model.VariantType==Variant.Type.Object&&model.AsGodotObject() is Resource resource&&resource.HasMethod("component")){var components=resource.Get("components").AsGodotArray();if(components.Count>0)title=components[0].As<Resource>().Get("title").AsString();}var dimensions=source.Get("dimensions").AsVector2();next.Get("prop_rules").AsGodotArray().Add(new Settings {["id"]=Guid.NewGuid().ToString("N"),["name"]=title,["mode"]=mode,["model"]=model,["spacing"]=12.0,["setback"]=2.0,["sides"]="Both",["seed"]=source.Get("seed"),["bounds"]=new Rect2(-dimensions*.45f,dimensions*.9f),["density"]=.02,["budget"]=2000,["yaw"]=0.0,["scale_range"]=Vector2.One,["enabled"]=true,["collisions"]=false,["biome_ids"]=Array.Empty<string>(),["slope_range"]=new Vector2(0,40),["height_range"]=new Vector2(-10000,10000),["anchors"]=new GArray()});return next;
    }
    public Settings build(Resource document,Resource source,Settings layout,Settings graph,Settings cancellation)
    {if(!Get(cancellation,"enabled",false).AsBool())return Build(document,source,layout,graph,()=>false);var bridge=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/world/world_props.gd");return Build(document,source,layout,graph,()=>bridge.Call("_cancel_requested",cancellation).AsBool());}
    internal Settings Build(Resource document,Resource source,Settings layout,Settings graph,Func<bool> cancelled)
    {
        var settings=new Settings();var errors=new List<string>();Settings Result()=>new() {["settings"]=settings,["warnings"]=Array.Empty<string>(),["errors"]=errors.ToArray()};var props=source.Get("prop_rules").AsGodotArray();if(props.Count==0)return Result();var field=source.Get("terrain_field").As<RefCounted>();if(field==null){errors.Add("Choose a terrain before populating objects.");return Result();}var toGround=field.Get("to_ground").AsTransform3D();
        foreach(var value in props)
        {
            if(cancelled())return new Settings {["cancelled"]=true};var rule=value.AsGodotDictionary();if(!Get(rule,"enabled",true).AsBool())continue;var rules=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/environment_scatter.gd").New().As<Resource>();rules.Set("terrain_id",source.Get("terrain_id"));rules.Get("palette").AsGodotArray().Add(new Settings {["source"]=rule["model"],["weight"]=1.0});rules.Set("seed",rule["seed"].AsInt64());rules.Set("density",Math.Clamp(Get(rule,"density",.02).AsDouble(),0,100));rules.Set("budget",Math.Clamp(Get(rule,"budget",2000).AsInt32(),1,20000));rules.Set("minimum_distance",rule["spacing"].AsDouble()*.5);rules.Set("scale_range",Get(rule,"scale_range",Vector2.One));rules.Set("yaw_range",Vector2.One*Get(rule,"yaw",0.0).AsSingle());rules.Set("align_normal",false);rules.Set("collisions",Get(rule,"collisions",false));rules.Set("slope_range",Get(rule,"slope_range",new Vector2(0,40)));rules.Set("height_range",Get(rule,"height_range",new Vector2(-10000,10000)));rules.Set("biome_ids",Get(rule,"biome_ids",Array.Empty<string>()));rules.Set("exclude_polygons",_forests.development(source,layout,graph,toGround,false));var polygon=_forests.rectangle(rule["bounds"].AsRect2(),toGround);rules.Get("include_polygons").AsGodotArray().Add(polygon);rules.Set("water_depth_range",new Vector2(0,.03f));string mode=rule["mode"].AsString();if(Get(rule,"sidewalk",false).AsBool()&&mode=="Roadside"){rules.Set("exclude_polygons",_forests.development(source,layout,graph,toGround,true));rules.Set("anchor_height_mode",2);}rules.Set("render_cluster_size",32.0);double distance=source.Get("render_distance").AsDouble();rules.Set("render_distance",distance>0?Math.Min(distance,300):0);rules.Set("lod_enabled",true);rules.Set("stream_instances",true);var bounds=new Rect2(polygon[0],Vector2.Zero);foreach(var point in polygon)bounds=bounds.Expand(point);rules.Set("region",bounds);
            if(mode is "Roadside" or "Grid" or "Anchors"){rules.Set("use_anchors",true);var positions=Anchors(rule,graph,cancelled);if(Get(positions,"cancelled",false).AsBool())return new Settings {["cancelled"]=true};string error=Get(positions,"error","").AsString();if(error.Length>0){errors.Add(error);continue;}rules.Set("anchor_ids",positions["ids"]);foreach(var pose in positions["poses"].AsGodotArray())rules.Get("anchor_points").AsGodotArray().Add(toGround*pose.AsTransform3D());}else if(mode=="Clusters"){double spacing=rule["spacing"].AsDouble();rules.Set("cluster_count",(int)Math.Clamp(Math.Ceiling(rule["bounds"].AsRect2().Area/(spacing*spacing*8)),1,512));rules.Set("cluster_radius",spacing*2);}
            string owner=source.Get("world_id").AsString(),id=owner+":props:"+rule["id"].AsString();var item=_forests.component(source,"unused",rule["name"].AsString(),owner);item.Set("id",id);var parameters=item.Get("parameters").AsGodotDictionary();parameters["world_key"]=id[owner.Length..];parameters["world_placement"]=rule["id"];item.Set("transform",field.Get("to_world"));parameters["world_pose"]=item.Get("transform");parameters["world_scatter_defaults"]=_forests.baseline(rules);var proxy=ModelPrimitives.Box(new Vector3(bounds.Size.X,.05f,bounds.Size.Y));var center=bounds.GetCenter();for(int vertex=0;vertex<proxy.Points.Count;vertex++)proxy.Points[vertex]+=new Vector3(center.X,0,center.Y);var mesh=proxy.Build();item.Set("mesh",mesh);parameters["world_mesh_key"]=unchecked((uint)GD.Hash(new GArray {mesh.Get("vertices"),mesh.Get("faces")}));document.Get("components").AsGodotArray().Add(item);settings[id]=new Settings {["kind"]="scatter",["scatter"]=rules,["collision"]=rules.Get("collisions")};
        }
        return Result();
    }
    public Settings anchors(Settings rule,Settings graph,Settings cancellation)
    {if(!Get(cancellation,"enabled",false).AsBool())return Anchors(rule,graph,()=>false);var bridge=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/world/world_props.gd");return Anchors(rule,graph,()=>bridge.Call("_cancel_requested",cancellation).AsBool());}
    private sealed class Road
    {internal readonly List<Vector3> Points=new();internal double Width,Outer,Sidewalk,Curb;}
    internal Settings Anchors(Settings rule,Settings graph,Func<bool> cancelled)
    {
        var poses=new Godot.Collections.Array<Transform3D>();var ids=new List<string>();double spacing=rule["spacing"].AsDouble();string mode=rule["mode"].AsString(),ruleId=rule["id"].AsString();
        if(mode=="Anchors"){var anchors=Get(rule,"anchors",new GArray()).AsGodotArray();for(int index=0;index<anchors.Count;index++){poses.Add(anchors[index].AsTransform3D());ids.Add(ruleId+":"+index);}}
        else if(mode=="Grid"){var bounds=rule["bounds"].AsRect2();double columnsValue=Math.Max(1,Math.Floor(bounds.Size.X/spacing)),rowsValue=Math.Max(1,Math.Floor(bounds.Size.Y/spacing));if(columnsValue*rowsValue>20000)return new Settings {["error"]="Grid placement exceeds 20,000 anchors. Increase spacing or shrink the region."};int columns=(int)columnsValue,rows=(int)rowsValue;var start=bounds.GetCenter()-new Vector2(columns-1,rows-1)*(float)spacing*.5f;for(int z=0;z<rows;z++){if(cancelled())return new Settings {["cancelled"]=true};for(int x=0;x<columns;x++){poses.Add(new Transform3D(Basis.Identity,new Vector3((float)(start.X+x*spacing),0,(float)(start.Y+z*spacing))));ids.Add(ruleId+":grid:"+x+":"+z);}}}
        else
        {
            var roads=new Dictionary<string,Road>(StringComparer.Ordinal);var order=new List<string>();var types=Get(rule,"road_types",Array.Empty<string>()).AsStringArray();bool sidewalk=Get(rule,"sidewalk",false).AsBool();foreach(var value in graph["edges"].AsGodotArray()){var edge=value.AsGodotDictionary();if(Get(edge,"mode","Ground").AsString()!="Ground")continue;if(types.Length>0&&!types.Contains(Get(edge,"type","Residential Street").AsString()))continue;if(sidewalk&&(!Get(edge,"section",false).AsBool()||Get(edge,"sidewalk",0.0).AsDouble()<.6))continue;string id=Get(edge,"source_road_id",edge["id"]).AsString();if(!roads.TryGetValue(id,out var road)){road=new Road {Width=edge["width"].AsDouble(),Outer=_sections.outer_half(edge),Sidewalk=edge["width"].AsDouble()*.5+Get(edge,"shoulder",0.0).AsDouble()+Get(edge,"curb_width",.14).AsDouble()+Get(edge,"sidewalk",0.0).AsDouble()*.5,Curb=Get(edge,"curb_height",0.0).AsDouble()};roads[id]=road;order.Add(id);}foreach(var point in edge["points"].AsVector3Array())if(road.Points.Count==0||road.Points[^1].DistanceTo(point)>.001)road.Points.Add(point);}
            foreach(string id in order){var road=roads[id];var points=road.Points;double total=0,next=spacing*.5;int step=0;for(int segment=0;segment<points.Count-1;segment++){if(cancelled())return new Settings {["cancelled"]=true};var a=points[segment];var b=points[segment+1];var delta=b-a;delta.Y=0;double length=delta.Length();if(length<.001)continue;var direction=delta/(float)length;var side=new Vector3(-direction.Z,0,direction.X);while(next<total+length){var center=a.Lerp(b,(float)((next-total)/length));foreach(float sign in new[]{-1f,1f}){string selected=Get(rule,"sides","Both").AsString();if(selected=="Left"&&sign>0||selected=="Right"&&sign<0)continue;double offset=sidewalk?road.Sidewalk:road.Outer+Math.Max(.1,Get(rule,"setback",2.0).AsDouble());var position=center+side*sign*(float)offset;if(sidewalk)position.Y=(float)(position.Y+road.Curb+.015);poses.Add(new Transform3D(Basis.LookingAt(-side*sign,Vector3.Up),position));ids.Add(ruleId+":"+id+":"+step+":"+(sign<0?"-1.0":"1.0"));if(poses.Count>20000)return new Settings {["error"]="Roadside placement exceeds 20,000 anchors. Increase spacing or populate a smaller world."};}step++;next+=spacing;}total+=length;}}
        }
        return new Settings {["poses"]=poses,["ids"]=ids.ToArray(),["error"]=""};
    }
}
